var APP=APPEARANCE+'/Clean';var p=H.page('Proto iOS '+APPEARANCE);var s=p.layers.find(l=>l.name==='Screen/ios/'+APP+'/'+ID);var b=s.layers.find(l=>l.name==='body');if(ID==='settings-appearance'){var options=b.layers.find(l=>l.name==='group 2');var footer=options.layers.find(l=>l.name==='footer');footer.parent=b;var seg=b.layers.find(l=>l.name==='segmented-control');footer.index=seg.index;footer.stackLayout.padding={top:0,right:16,bottom:0,left:16};footer.stackLayout.apply();options.stackLayout.apply();b.stackLayout.apply();}if(ID==='artifacts--share'){var sh=s.layers.find(l=>l.name==='sheet');var sb=sh.layers.find(l=>l.name==='sheet-body');var g=sb.layers.find(l=>l.name==='group 2');var rs=g.layers.find(l=>l.name==='rows');var row=rs.layers.find(l=>l.name==='link:project');row.style.fills=[{fillType:sketch.Style.FillType.Color,color:H.sw(APP,'accent'),enabled:true}];function color(l){if(l.type==='Text')l.style.textColor='#ffffff';(l.layers||[]).forEach(color);}color(row);}console.log(JSON.stringify({id:ID,appearance:APPEARANCE,frame:s.id}));